command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9dd0316236849b18956117a592b21124f2d67c0b"
$branch="work/removable-transfer-20261006"
$expected="f4daef6319efd1d733c62e1233c999ba7cf3cac9"
Set-Location -LiteralPath $repo
& git fetch origin main --no-tags --prune
if($LASTEXITCODE -ne 0){throw "branch cleanup fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before branch cleanup"}
$lines=@(& git ls-remote --heads origin ("refs/heads/"+$branch))
if($LASTEXITCODE -ne 0){throw "branch lookup failed: $branch"}
if($lines.Count -eq 0){Write-Host "BRANCH_ALREADY_ABSENT=$branch";Write-Host "BRANCH_CLEANUP=PASS";exit 0}
$observed=(($lines[0] -split "\s+")[0])
if($observed -ne $expected){throw "branch cleanup lease mismatch: $branch expected=$expected observed=$observed"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "branch deletion failed: $branch"}
$after=@(& git ls-remote --heads origin ("refs/heads/"+$branch))
if($LASTEXITCODE -ne 0){throw "branch verify failed: $branch"}
if($after.Count -ne 0){throw "branch still exists after deletion: $branch"}
Write-Host "BRANCH_DELETED=$branch"
Write-Host "BRANCH_CLEANUP=PASS"
